class Unfold<T> extends Spliterators.AbstractSpliterator<T> {
    private T state;                       // seed, replaced each step
    private final UnaryOperator<T> step;   // null result = stop
    public boolean tryAdvance(Consumer<? super T> action) {
        if (state == null) return false;
        action.accept(state);              // emit one layer
        state = step.apply(state);         // next seed
        return true;
    }
}
